/bin/bash -lc "python - <<'PY'
import pathlib, csv, json, math
outdir=pathlib.Path('codex_output/galaxy_results')
paths={'full':outdir/'full_deseq2.tsv','without_third':outdir/'without_third_deseq2.tsv'}
def parse_float(x):
    if x in ('NA','NaN','',None): return None
    try: v=float(x)
    except ValueError: return None
    return None if math.isnan(v) else v

def count_sig(path):
    n=0; total=0; bad=0
    examples=[]
    with open(path, newline='') as f:
        for row in csv.reader(f, delimiter='\\t'):
            if not row or row[0].startswith('#'):
                continue
            total+=1
            if len(row)<6:
                bad+=1; continue
            base=parse_float(row[1]); lfc=parse_float(row[2]); p=parse_float(row[4])
            if base is None or lfc is None or p is None:
                continue
            if p < 0.05 and abs(lfc) > 1 and base > 10:
                n+=1
                if len(examples)<3: examples.append(row[:6])
    return {'rows':total,'bad_rows':bad,'significant':n,'examples':examples}
res={k:count_sig(v) for k,v in paths.items()}
full=res['full']['significant']; sub=res['without_third']['significant']
if sub>full: direction='increase'
elif sub<full: direction='decrease'
else: direction='no change'
res['direction']=direction; res['delta']=sub-full
print(json.dumps(res, indent=2))
path=pathlib.Path('codex_output/answer.txt')
path.write_text(f\"{full} {sub} {direction}\\n\")
print('answer', path.read_text().strip())
PY"

